/* ==UserStyle==
@name snips.sh Catppuccin
@namespace github.com/catppuccin/userstyles/styles/snips-sh
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/snips-sh
@version 2026.11.01
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/snips-sh/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Asnips-sh
@description Soothing pastel theme for snips.sh
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/lib.less";

@-moz-document domain("snips.sh") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }
  @import (css)
    url("https://chroma.catppuccin.com/@{lightFlavor}-chroma-style.css")
    (prefers-color-scheme: light);
  @import (css)
    url("https://chroma.catppuccin.com/@{darkFlavor}-chroma-style.css")
    (prefers-color-scheme: dark);

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --color-primary: @accent !important;
    --color-surface-0: @base;
    --color-surface-1: @mantle;
    --color-surface-2: @surface0;
    --color-border: @surface0;
    --color-gray: @subtext0;
    --color-blue: @blue;
    --color-red: @red;
    --color-amber: @yellow;
    --color-green: @green;
    --color-teal: @teal;
    --color-purple: @mauve;
    --color-pink: @pink;
    --color-white: @text;
  }
}

sections.code:
@import url("https://chroma.catppuccin.com/latte-chroma-style.css") (prefers-color-scheme: light);
@import url("https://chroma.catppuccin.com/mocha-chroma-style.css") (prefers-color-scheme: dark);
@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
    --color-primary: #8839ef !important;
    --color-surface-0: #eff1f5;
    --color-surface-1: #e6e9ef;
    --color-surface-2: #ccd0da;
    --color-border: #ccd0da;
    --color-gray: #6c6f85;
    --color-blue: #1e66f5;
    --color-red: #d20f39;
    --color-amber: #df8e1d;
    --color-green: #40a02b;
    --color-teal: #179299;
    --color-purple: #8839ef;
    --color-pink: #ea76cb;
    --color-white: #4c4f69;
  }
  :root ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #6c6f85 !important;
  }
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --color-primary: #cba6f7 !important;
    --color-surface-0: #1e1e2e;
    --color-surface-1: #181825;
    --color-surface-2: #313244;
    --color-border: #313244;
    --color-gray: #a6adc8;
    --color-blue: #89b4fa;
    --color-red: #f38ba8;
    --color-amber: #f9e2af;
    --color-green: #a6e3a1;
    --color-teal: #94e2d5;
    --color-purple: #cba6f7;
    --color-pink: #f5c2e7;
    --color-white: #cdd6f4;
  }
  :root ::selection {
    background-color: rgba(203, 166, 247, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #a6adc8 !important;
  }
}
